-- CC_0307_hawaii_state_legislature_headshots.sql
-- Portraits for 74 of the 76 Hawaii legislators seated by CC_0306.
--
-- GENERATED by scripts/gen-hi-legislature-headshots.mjs. Do not hand-edit.
--
-- ═══ ALL THREE FIELDS, AND WHY ═══
--
--   politicians.photo_custom_url   THE FIELD THAT RENDERS. The address-search read path
--                                  builds its photo from COALESCE(photo_custom_url,
--                                  photo_origin_url) and never reads politician_images.
--   essentials.politician_images   carries photo_license, which the API returns to the
--                                  frontend, and the grid reads images[] FIRST.
--   politicians.photo_origin_url   provenance: the page the photograph came from.
--
-- ═══ 🔴 BOUND BY SEAT, NEVER BY NAME ═══
--
-- Production holds a DIFFERENT Mike Lee (U.S. Senator, Utah) and a DIFFERENT Chris Todd
-- (Tennessee House District 73). A name-bound UPDATE would paint a Hawaii representative's
-- face onto either of them. Every row below resolves through (chamber, district) -> office
-- -> office_current_holder, and the gate asserts the resolved name matches the one this file
-- was generated against.
--
-- ═══ LICENCE ═══
--
-- press_use for all 76: these are the Legislature's own official member photographs, served
-- from capitol.hawaii.gov/memberfiles/repsenphotos/. Not federal works, no free licence.
--
-- ═══ 🔴 ALL 76 WERE LOOKED AT ═══
--
-- All 76 rendered to two contact sheets and inspected before this file was written, because nothing
-- in this repo asks whether a headshot contains a face — a seal, a map, a blank or a torso
-- all pass every automated check. On the Honolulu seed that step caught a department SEAL
-- being imported as the Prosecuting Attorney's portrait. All 76 here are genuine, distinct
-- individual headshots. Senate District 18 (Bass) is an outdoor photograph rather than the
-- studio set, consistent with her appointment on 2026-08-09.
--
-- ⚠ Mirrored into Supabase storage, not hotlinked. The images are 13-641 KB at source and are
--   stored as uploaded; none was upscaled.

-- ── Pre-flight ────────────────────────────────────────────────────────────────
DO $$
DECLARE v_seated int; v_already int;
BEGIN
  SELECT count(och.politician_id) INTO v_seated
    FROM essentials.offices o JOIN essentials.chambers c ON c.id=o.chamber_id
    JOIN essentials.governments g ON g.id=c.government_id
    LEFT JOIN essentials.office_current_holder och ON och.office_id=o.id
   WHERE g.name='State of Hawaii' AND c.name IN ('Hawaii Senate', 'Hawaii House of Representatives');
  IF v_seated <> 76 THEN
    RAISE EXCEPTION 'CC_0307 pre-flight: expected 76 seated Hawaii legislators from CC_0306, found % — run CC_0306 first', v_seated;
  END IF;
  SELECT count(*) INTO v_already FROM essentials.politician_images pi
    JOIN essentials.office_current_holder och ON och.politician_id=pi.politician_id
    JOIN essentials.offices o ON o.id=och.office_id JOIN essentials.chambers c ON c.id=o.chamber_id
    JOIN essentials.governments g ON g.id=c.government_id
   WHERE g.name='State of Hawaii' AND c.name IN ('Hawaii Senate', 'Hawaii House of Representatives') AND pi.type='default';
  IF v_already <> 2 THEN
    RAISE EXCEPTION 'CC_0307 pre-flight: expected exactly 2 pre-existing default image rows (Senate 23 Awa and Senate 24 Keohokalole, loaded as congressional candidates), found % — read them before overwriting', v_already;
  END IF;
END $$;

CREATE TEMP TABLE hi_photos(
  ch text NOT NULL, district int NOT NULL, who text NOT NULL, file text NOT NULL, origin text NOT NULL,
  politician_id uuid, PRIMARY KEY (ch, district)) ON COMMIT DROP;

