-- Resolve by SEAT.
UPDATE hi_photos h SET politician_id = och.politician_id
  FROM essentials.offices o
  JOIN essentials.districts d ON d.id=o.district_id
  JOIN essentials.chambers c ON c.id=o.chamber_id
  JOIN essentials.governments g ON g.id=c.government_id
  JOIN essentials.office_current_holder och ON och.office_id=o.id
 WHERE g.name='State of Hawaii'
   AND c.name = CASE h.ch WHEN 'S' THEN 'Hawaii Senate' ELSE 'Hawaii House of Representatives' END
   AND d.mtfcc = CASE h.ch WHEN 'S' THEN 'G5210' ELSE 'G5220' END
   AND d.geo_id = '15' || lpad(h.district::text, 3, '0');

-- 🔴 The seat must still hold the person this file was generated against.
DO $$
DECLARE v_miss int; v_wrong text;
BEGIN
  SELECT count(*) INTO v_miss FROM hi_photos WHERE politician_id IS NULL;
  IF v_miss <> 0 THEN RAISE EXCEPTION 'CC_0307: % seat(s) did not resolve to a holder', v_miss; END IF;
  SELECT string_agg(format('%s%s expected %L but holds %L', h.ch, h.district, h.who, p.full_name), '; ')
    INTO v_wrong FROM hi_photos h JOIN essentials.politicians p ON p.id=h.politician_id
   WHERE p.full_name <> h.who;
  IF v_wrong IS NOT NULL THEN
    RAISE EXCEPTION 'CC_0307: a portrait is bound to a seat whose holder has changed — %', v_wrong;
  END IF;
END $$;

-- 1. The field that renders.
UPDATE essentials.politicians p SET photo_custom_url = 'https://kxsdzaojfaibhuzmclfq.supabase.co/storage/v1/object/public/politician_photos/hi-legislature-2026/' || h.file
  FROM hi_photos h WHERE p.id = h.politician_id;

-- 2. The image row, which carries the licence to the frontend.
INSERT INTO essentials.politician_images (politician_id, url, type, photo_license)
SELECT h.politician_id, 'https://kxsdzaojfaibhuzmclfq.supabase.co/storage/v1/object/public/politician_photos/hi-legislature-2026/' || h.file, 'default', 'press_use'
  FROM hi_photos h
 WHERE NOT EXISTS (SELECT 1 FROM essentials.politician_images pi
                    WHERE pi.politician_id = h.politician_id AND pi.type='default');

-- 3. Provenance. Written last, never into the render position.
UPDATE essentials.politicians p SET photo_origin_url = h.origin
  FROM hi_photos h WHERE p.id = h.politician_id;

-- ── Post-verify gate ──────────────────────────────────────────────────────────
DO $$
DECLARE v_custom int; v_img int; v_disagree int; v_lic int; v_origin int; v_notjpg int; v_utah int;
BEGIN
  SELECT count(*) INTO v_custom FROM hi_photos h JOIN essentials.politicians p ON p.id=h.politician_id
   WHERE p.photo_custom_url LIKE 'https://kxsdzaojfaibhuzmclfq.supabase.co/storage/v1/object/public/politician_photos/hi-legislature-2026/%';
  IF v_custom <> 74 THEN RAISE EXCEPTION 'CC_0307 gate: expected 74 photo_custom_url on the CDN, found %', v_custom; END IF;

  SELECT count(*) INTO v_img FROM hi_photos h
    JOIN essentials.politician_images pi ON pi.politician_id=h.politician_id AND pi.type='default';
  IF v_img <> 74 THEN RAISE EXCEPTION 'CC_0307 gate: expected 74 default image rows, found %', v_img; END IF;

  -- The grid reads images[] first and the backend the scalar; disagreement shows two faces.
  SELECT count(*) INTO v_disagree FROM hi_photos h
    JOIN essentials.politicians p ON p.id=h.politician_id
    JOIN essentials.politician_images pi ON pi.politician_id=h.politician_id AND pi.type='default'
   WHERE pi.url IS DISTINCT FROM p.photo_custom_url;
  IF v_disagree <> 0 THEN RAISE EXCEPTION 'CC_0307 gate: % row(s) have images[].url disagreeing with photo_custom_url', v_disagree; END IF;

  SELECT count(*) INTO v_lic FROM hi_photos h
    JOIN essentials.politician_images pi ON pi.politician_id=h.politician_id AND pi.type='default'
   WHERE pi.photo_license <> 'press_use';
  IF v_lic <> 0 THEN RAISE EXCEPTION 'CC_0307 gate: % image row(s) missing the press_use licence', v_lic; END IF;

  SELECT count(*) INTO v_origin FROM hi_photos h JOIN essentials.politicians p ON p.id=h.politician_id
   WHERE p.photo_origin_url = h.origin;
  IF v_origin <> 74 THEN RAISE EXCEPTION 'CC_0307 gate: expected 74 photo_origin_url, found %', v_origin; END IF;

  SELECT count(*) INTO v_notjpg FROM hi_photos h JOIN essentials.politicians p ON p.id=h.politician_id
   WHERE p.photo_custom_url NOT LIKE '%.jpg';
  IF v_notjpg <> 0 THEN RAISE EXCEPTION 'CC_0307 gate: % photo_custom_url value(s) are not image files', v_notjpg; END IF;

  -- 🔴 The Utah senator and the Tennessee representative were NOT repainted.
  SELECT count(*) INTO v_utah FROM essentials.politicians
   WHERE external_id IN (-400077, -4720073) AND coalesce(photo_custom_url,'') LIKE 'https://kxsdzaojfaibhuzmclfq.supabase.co/storage/v1/object/public/politician_photos/hi-legislature-2026/%';
  IF v_utah <> 0 THEN
    RAISE EXCEPTION 'CC_0307 gate: % Hawaii portrait(s) landed on the Utah Mike Lee or the Tennessee Chris Todd', v_utah;
  END IF;

  RAISE NOTICE 'CC_0307 OK: 74 legislator portraits — scalar, image row and provenance all agree.';
END $$;
